import fs from "node:fs/promises";
const source = "supabase/migrations/20261106000000_saas3_experience.sql";
const target = "supabase/saas3-install.sql";
const sql =
  "-- GENERATED by node scripts/build-saas3-sql.mjs. Review and execute manually AFTER SaaS 2.0.\n-- No production execution by this script. Same ledger; no bookings/payments recreated.\n" +
  (await fs.readFile(source, "utf8"));
if (process.argv.includes("--check")) {
  if ((await fs.readFile(target, "utf8")) !== sql)
    throw Error("Instalador SaaS 3 desatualizado");
  console.log("Instalador SaaS 3 sincronizado");
} else await fs.writeFile(target, sql);
